        'help' => [
            'site_name' => 'Nombre del sitio que se muestra en la parte superior izquierda de la página.',
            'site_name_short' => 'Abreviatura del nombre del sitio que se muestra cuando el menú está contraído.',
            'site_logo' => 'Logotipo del sitio. Tamaño recomendado: 200px * 40px',
            'site_logo_mini' => 'Logotipo del sitio (tamaño pequeño). Tamaño recomendado: 40px * 40px',
            'site_favicon' => 'Favicon del sitio (.ico). Se utiliza, por ejemplo, en los marcadores. Tamaño recomendado: 16px * 16px',
            'site_skin' => 'Seleccione el color del tema del sitio. *Tras guardar, se aplicará al volver a cargar la página.',
            'site_layout' => 'Seleccione el diseño del menú del sitio, situado a la izquierda de la página. *Tras guardar, se aplicará al volver a cargar la página.',
            'ui_design' => 'Seleccione el diseño de la página de inicio de sesión y de las páginas de administración. "Moderno" es el nuevo diseño en blanco y gris; "Clásico" es el diseño utilizado hasta ahora. El valor predeterminado es "Moderno". Para volver al diseño anterior, seleccione "Clásico". *Tras guardar, se aplicará al volver a cargar la página.<br/>Si el diseño está definido por el servidor (EXMENT_UI_DESIGN en .env), ese valor tiene prioridad y no se puede cambiar aquí.',
            'filter_search_type' => 'Configure el método de búsqueda de los datos registrados. *En el caso de la coincidencia parcial, el rendimiento puede verse afectado según la cantidad de datos.',
            'grid_filter_disable_flg' => 'Los elementos marcados se ocultarán en los filtros de la página de la lista de datos.',
            'system_values_pos' => 'Configure la posición en la que se muestran los elementos del sistema en las pantallas de edición y de detalles de los datos.',
            'data_submit_redirect' => 'Puede configurar la página predeterminada a la que se redirige tras guardar datos personalizados. Si configura este elemento, la casilla del destino tras guardar quedará marcada en la página de introducción de datos.',
            'header_user_info' => 'Puede configurar el contenido que se muestra en la información del usuario del encabezado. Si se deja en blanco, se ocultará.',
            'allowed_locales' => 'Los idiomas que los usuarios pueden elegir en el menú de arriba a la derecha, en la página de inicio de sesión y en su configuración. Vacío significa todos los idiomas instalados. El idioma del sitio siempre se puede elegir.',
            'locale_from_browser' => 'Con SÍ, un usuario que no ha elegido idioma ve las páginas en el idioma del navegador (entre los idiomas que se pueden elegir). Con NO, en el idioma del sitio.',
            'api_available' => 'Cree una clave de Laravel antes de seleccionar SÍ. Consulte <a href="%suse-api" target="_blank">aquí<i class="fa fa-external-link"></i></a>. Si selecciona SÍ, podrá usar la API.',
            'outside_api' => 'Si selecciona SÍ, se podrán ejecutar procesos que se comunican con servidores externos, como la notificación de la última versión de Exment. Solo se reciben datos. *Si no desea realizar comunicaciones, por ejemplo, cuando se utiliza en un entorno sin conexión a una red externa, seleccione NO.',
            'grid_pager_count' => 'Es el número predeterminado de elementos que se muestran en las páginas de lista. Se aplica a todo el sistema.',
            'datalist_pager_count' => 'Es el número predeterminado de datos que se muestran en la búsqueda por palabra clave y en las listas de datos del panel. Se aplica a todo el sistema.',
            'meili_host' => 'p. ej.: http://127.0.0.1:7700',
            'meili_key' => 'Clave de API maestra del servidor Meilisearch. Se guarda cifrada. Si deja este campo vacío, se guarda una clave vacía y se utiliza en su lugar el valor MEILISEARCH_KEY de .env.',
            'meili_index' => 'Nombre del índice combinado, p. ej. exment_global. Después de cambiarlo, ejecute `php artisan exment:meili-index` para reconstruirlo.',
            'meili_global_search' => 'Desactivado: se vuelve a la búsqueda MySQL predeterminada de Exment.',
            'meili_realtime_sync' => 'Activado: los cambios en los registros se sincronizan automáticamente con Meilisearch (a través de la cola). Los procesos de cola leen la configuración al iniciarse; reinícielos después de cambiar la configuración de Meilisearch.',
            'meili_batch_size' => 'Número de documentos enviados por lote al indexar (p. ej. 1000).',
            'meili_repair_enabled' => 'Activado: repara a diario las diferencias entre la base de datos y el índice (requiere el programador de tareas).',
            'meili_repair_at' => 'Hora de ejecución de la reparación (24 h, HH:MM, p. ej. 03:00).',
            'meili_filter_mode' => '"Automático + personalizado" = selección automática según el tipo de columna, más las columnas añadidas o excluidas en la pantalla de configuración. "Solo personalizado" = solo las columnas configuradas en la pantalla. Es necesario volver a indexar después del cambio.',
            'meili_dictionary' => 'Ajuste la relevancia de la búsqueda con sinónimos y palabras vacías. Solo cambia la configuración del índice, por lo que no es necesario volver a indexar tras guardar (se aplica en segundos).',
            'meili_dictionary_type' => '"Sinónimo" = un grupo de términos tratados como equivalentes. "Palabra vacía" = términos que se ignoran durante la búsqueda (partículas, etc.).',
            'meili_dictionary_word' => 'Sinónimo = el término principal del grupo. Palabra vacía = la(s) palabra(s) que se ignoran (separe varias con comas o saltos de línea).',
            'meili_dictionary_synonyms' => 'Términos tratados como equivalentes a la palabra principal, separados por comas o saltos de línea (p. ej. contract, agreement). Todos pasan a ser sinónimos entre sí.',
            'meili_filter_alias' => 'Las columnas con el mismo significado (p. ej. status, contract_status) que comparten un alias se combinan en un único grupo de filtros. Solo para filtros de igualdad; al cambiar el alias, se vuelve a indexar automáticamente al guardar.',
            'meili_filter_include_mode' => 'Incluir: añade la columna al filtro. Excluir: quita una columna automática del filtro (solo se aplica en el modo "Automático + personalizado").',
            'permission_available' => 'Si selecciona SÍ, se gestionan los elementos a los que se puede acceder según el usuario o el rol.',
            'organization_available' => 'Si selecciona SÍ, se crean las organizaciones y departamentos a los que pertenecen los usuarios.',
            'logging_toggle_available' => 'Si selecciona SÍ, las operaciones lentas en pantalla se guardan en el "Registro de rendimiento del sistema" (menú "Configuración: Sistema"): la URL de la pantalla (los valores de búsquedas, etc. se ocultan), el usuario, el tiempo y la consulta SQL (con "?", sin los valores).',
            'logging_slow_request_seconds' => 'Se guarda el registro cuando una pantalla tarda este número de segundos o más. 0: no se registra por esta condición. Si este valor y "segundos de una consulta SQL lenta" son ambos 0, se guardan todas las operaciones (úselo solo para investigaciones).',
            'logging_slow_sql_seconds' => 'Se guarda el registro cuando una consulta SQL tarda este número de segundos o más. 0: no se registra por esta condición.',
            'logging_max_per_hour' => 'Número máximo de registros guardados en una hora. Los registros que lo superen no se guardan. 0: sin límite.',
            'system_admin_users' => 'Configure el usuario que será el administrador del sistema.',
            'system_mail' => 'Configure el envío de correos electrónicos desde el sistema.',
            'system_mail_from' => 'Dirección de correo del remitente. Los correos se envían con esta dirección como "From".',
            'system_mail_from_view_name' => 'Introduzca el nombre visible del remitente. Se mostrará al destinatario. *Si ha introducido el nombre visible del remitente en la plantilla de notificación, esa configuración tiene prioridad. Puede introducir parámetros.',
            'system_mail_encryption' => 'Introduzca en minúsculas el protocolo de cifrado del correo (ssl, tls, etc.).',
            'system_mail_body_type' => 'Seleccione el tipo de cuerpo del correo electrónico que desea enviar.',
            'test_mail' => 'Envía un correo de prueba al destinatario introducido. <br /> <b>*Asegúrese de guardar la configuración de correo anterior antes de ejecutarlo. La configuración que se está introduciendo no es válida. </b>',
            'system_slack_user_column' => 'Seleccione la columna personalizada de la tabla de usuarios en la que se configura el ID de Slack. Al enviar notificaciones de Slack, se puede añadir una mención a ese ID de usuario.',
            'system_line_oa_basic_id' => 'El Basic ID de la cuenta oficial de LINE (empieza por @). Se utiliza para generar el enlace profundo de vinculación de la cuenta.',
            'safety_check_auto_enabled' => 'Si selecciona SÍ, se envía automáticamente una notificación cuando se detecta un terremoto igual o superior a la "Intensidad sísmica mínima para el envío automático".',
            'safety_check_min_scale' => 'Se envía automáticamente una notificación cuando se detecta un terremoto igual o superior a la intensidad sísmica seleccionada (máxima a nivel nacional).',
            'safety_check_cooldown_minutes' => 'Intervalo antes de volver a enviar para el mismo terremoto.<br/>Ejemplo: si se reciben boletines del mismo terremoto entre las 02:02 y las 02:12, con un intervalo de 60 minutos se envía una vez a las 02:02, mientras que con 5 minutos se envía dos veces, a las 02:02 y a las 02:12.<br/>Para un terremoto distinto, la notificación se envía independientemente de este intervalo.',
