            'chip' => 'Chip con texto',
            'bar' => 'Solo barra de color',
        ],
        'description_custom_view_columns' => 'Seleccione las columnas que se mostrarán en la vista.',
        'description_custom_view_kanban_columns' => 'Seleccione las columnas que se muestran en la tarjeta. "Posición" decide en qué parte de la tarjeta aparecen y "Estilo" elige un ajuste predefinido de aspecto de celda (etiqueta, píldora, insignia, etc.); es la misma biblioteca que usa la lista de datos, por lo que un aspecto se define una sola vez y se aplica en ambas pantallas.<br/>*Si se deja vacío, la tarjeta sigue la configuración de la columna y, si esta no tiene ninguna, muestra "nombre y valor".<br/>*"Icono" admite un nombre de clase de Font Awesome (por ejemplo, fa-phone). Con pares "valor:clase" separados por comas, cada valor puede tener su propio icono.<br/>*Si no se configura, la tarjeta muestra solo el título.',
        'description_custom_view_calendar_columns' => 'Seleccione la columna de fecha que se mostrará en el calendario.<br/>* Si las columnas personalizadas no aparecen en "Columna de destino", no se han configurado los <a href="%s" target="_blank">índices de búsqueda<i class="fa fa-external-link"></i></a>. Revise el contenido del enlace y configúrelos.',
        'description_custom_view_groups' => 'Configura las columnas clave de agrupación que se muestran en la vista.<br />*Si las columnas personalizadas no aparecen en "Columna de destino", no se ha configurado el <a href="%s" target="_blank">índice de búsqueda<i class="fa fa-external-link"></i></a>. Revise el contenido del enlace y configúrelo.',
        'description_custom_view_summaries' => 'Configura las columnas de resumen de los datos que se muestran en la vista.<br/>*Las columnas que se pueden resumir son las de tipo "ID", "Entero", "Decimal", "Moneda" y "Fecha". Para contar el número total de registros, elija "ID" como columna de destino y "Recuento" como tipo de resumen.',
        'description_custom_view_sorts' => 'Configura el orden de visualización de los datos que se muestran en la vista. Si registra dos o más, el rendimiento puede disminuir en tablas con muchísimos datos.<br />*Si las columnas personalizadas no aparecen en "Columna de destino", no se ha configurado el <a href="%s" target="_blank">índice de búsqueda<i class="fa fa-external-link"></i></a>. Revise el contenido del enlace y configúrelo.',
        'description_custom_view_filters' => 'Configure las condiciones de los datos que se muestran en la vista.<br/>* Además de esta configuración, los datos se filtran para mostrar solo aquellos sobre los que el usuario con acceso tiene permiso.<br />*Si las columnas personalizadas no aparecen en "Columna de destino", no se ha configurado el <a href="%s" target="_blank">índice de búsqueda<i class="fa fa-external-link"></i></a>. Revise el contenido del enlace y configúrelo.',
        'description_custom_view_grid_filters' => 'Especifique las columnas que se mostrarán como opciones en el "Filtro" que aparece en la parte superior de la vista.<br/>*Si desea mostrar los elementos predeterminados del sistema, no añada columnas a esta lista.<br/>*Si la columna personalizada no aparece en "Columna de destino", no se ha configurado el <a href="%s" target="_blank">índice de búsqueda<i class="fa fa-external-link"></i></a>. Revise el contenido del enlace y configúrelo.',
        'description_custom_view_summary_filters' => '<br/>*Este "filtro" sirve para acotar los datos antes del resumen, no los resultados resumidos.',
        'help' => [
            'custom_view_type' => 'Vista del sistema: vista disponible para todos los usuarios de esta tabla. Vista de usuario: vista disponible solo para el usuario que la creó.',
            'grid_preset' => 'Muestra esta columna en la lista de datos con el ajuste predefinido elegido.<br/>Tiene prioridad sobre la configuración de la columna.<br/>Use el botón del lápiz para crear o editar un ajuste predefinido.',
            'sort_type' => 'Especifica si se ordena de forma ascendente (de menor a mayor) o descendente (de mayor a menor).',
            'sort_order_summaries' => 'Ordena los datos que se obtienen.<br />Ordena de menor a mayor número entre las "columnas de agrupación" y las "columnas de resumen".',
            'use_view_infobox' => 'Si selecciona SÍ, puede configurar un cuadro de información en la parte superior de la vista donde escribir detalles del trabajo y mensajes para los usuarios.',
            'view_infobox_title' => 'Introduzca el título que se mostrará en el cuadro de información.',
            'view_infobox' => 'Introduzca el HTML que se mostrará en el cuadro de información. *No se pueden introducir imágenes ni scripts.',
            'order' => 'Orden de visualización de los botones de menú de las vistas personalizadas.',
            'kanban_group_column' => 'Las opciones de esta columna se convierten en las columnas del tablero Kanban.<br/>*Solo se pueden elegir columnas de opciones de un único valor. No se usa cuando "Cómo se crean las columnas del tablero" es "A partir de los estados del flujo de trabajo".',
            'kanban_swimlane_column' => 'Divide el tablero horizontalmente en carriles según el valor de esta columna.<br/>*Si no se configura, el tablero se muestra sin dividir.',
            'kanban_editable' => 'Si selecciona SÍ, al arrastrar una tarjeta a otra columna del tablero se actualiza el valor de "Columna para las columnas del tablero".<br/>*Los usuarios sin permiso de edición no pueden arrastrar aunque esté en SÍ.',
            'kanban_max_count' => 'Número máximo de registros mostrados en el tablero. Un número elevado ralentiza la página.',
            'gantt_start_column' => 'Columna de fecha en la que empieza la barra.',
            'gantt_end_column' => 'Columna de fecha en la que termina la barra.<br/>*Un registro con esta fecha ya pasada y un progreso inferior a 100 se muestra con un borde rojo de "vencido".',
            'gantt_color_column' => 'Las barras se colorean según los valores de esta columna.<br/>*Se usan tal cual los colores definidos en la configuración de colores por valor de la columna.',
            'gantt_progress_column' => 'El progreso (%) se dibuja como una superposición más oscura dentro de la barra.',
            'gantt_group_column' => 'Las filas se agrupan según los valores de esta columna.<br/>*Para una columna select_table (una tabla de hitos, etc.), la primera columna de fecha de la tabla de destino se muestra como el rombo de fecha límite.',
            'gantt_parent_column' => 'Elija una columna que haga referencia a esta misma tabla y los registros hijos se mostrarán con sangría bajo su padre.',
            'gantt_assignee_column' => 'Elija una columna de usuario para mostrar un avatar en cada fila.',
            'gantt_max_count' => 'Número máximo de registros dibujados en el gráfico (10-2000, valor predeterminado 500).',
            'kanban_source' => 'De dónde proceden las columnas del tablero Kanban.<br/>*A partir de una columna de opciones: sus opciones se convierten en las columnas.<br/>*A partir del flujo de trabajo: los estados del flujo de trabajo aplicado a esta tabla se convierten en las columnas. Al arrastrar una tarjeta se abre la acción del flujo de trabajo que lleva a ese estado, por lo que se rechaza cualquier movimiento que el flujo de trabajo no permita.',
            'kanban_wip_enforce' => 'Qué ocurre cuando se suelta una tarjeta en una columna que ya está en su límite WIP.<br/>"Permitirlo" mantiene el comportamiento anterior: el encabezado se vuelve rojo y la tarjeta se mueve igualmente.<br/>"Preguntar antes" muestra una confirmación y mueve la tarjeta solo si usted acepta.<br/>"No permitirlo" atenúa en gris la columna llena durante el arrastre y rechaza la operación.<br/>*Las columnas sin límite WIP nunca se ven afectadas.<br/>*Las tarjetas que coinciden con "Valores considerados como urgentes" están exentas de esta regla (en Kanban, las urgencias pueden superar el límite), pero se siguen contando, por lo que la columna sigue mostrándose por encima de su límite.',
            'kanban_policies' => 'Una regla que se muestra en el encabezado de la columna; pase el cursor sobre la marca para leerla.<br/>Ejemplo: en la columna "En pruebas" escriba "todos los elementos de la hoja de pruebas aprobados antes de avanzar" y la condición de salida será visible para todo el equipo.<br/>*La columna de destino se elige entre los valores de la tabla (o los estados del flujo de trabajo).<br/>*Se ignora cualquier configuración que no coincida con las columnas que se muestran actualmente.',
            'kanban_wips' => 'Número máximo de tarjetas que puede contener una columna. La columna de destino se elige entre los valores de la tabla (o los estados del flujo de trabajo), nunca se escribe a mano.<br/>*Una columna que supera su límite muestra el encabezado en rojo.<br/>*Se ignora cualquier configuración que no coincida con las columnas que se muestran actualmente.',
            'kanban_done_keys' => 'Columnas del tablero que significan "terminado", elegidas entre los valores de la tabla.<br/>*Esos registros detienen la cuenta atrás de la fecha límite y se cuentan como "Terminados" en la barra de resumen.<br/>*En un tablero de flujo de trabajo, todo estado marcado como completado ya se considera terminado, por lo que no hace falta configurar nada aquí.<br/>*Se ignora cualquier configuración que no coincida con las columnas que se muestran actualmente.',
            'kanban_title_column' => 'Columna que se muestra como título en negrita dentro de la tarjeta.<br/>*Si se configura, el nombre visible del registro se muestra como enlace en la parte superior de la tarjeta.<br/>*Si no se configura, el propio nombre visible del registro se convierte en el título.',
            'kanban_assignee_column' => 'Columna que contiene el responsable.<br/>*Se muestra con un avatar en la parte inferior de la tarjeta; las tarjetas sin valor muestran "Sin asignar".<br/>*También la usan la barra de resumen, el filtro "Solo sin asignar" y la asignación masiva.<br/>*<b>Si se deja vacía</b>, el tablero no tiene avatar, ni indicador "Sin asignar", ni filtro "Solo sin asignar", ni asignación masiva, ni edición del responsable en la tarjeta, ni asignación automática. El botón "Míos" también desaparece, salvo que se indique una columna en "Columna que usa el botón "Míos"".',
            'kanban_mine_column' => 'Qué columna consulta el botón "Míos" de la barra de herramientas para decidir que una tarjeta es suya.<br/>*Si no se configura, se usa la columna del responsable. Indique la columna del solicitante para limitar el tablero a las peticiones que usted ha creado.<br/>*Se pueden usar columnas de usuario y de organización, así como una columna que haga referencia a una tabla con exactamente una columna de usuario (las filas vinculadas a usted se buscan a través de ella).<br/>*Si la columna no permite saber quién está mirando (por ejemplo, una columna de opciones simple), el botón no se muestra.',
            'kanban_filter_columns' => 'Elija solo las columnas que debe ofrecer el panel de filtros. Se muestran en el orden en que las elija.<br/>*Si no se configura, se ofrecen todas las columnas que lee el tablero (columnas agrupables, el responsable, los campos de la tarjeta, etc.), lo que resulta en una lista larga en tablas con muchas columnas.<br/>*El cuadro de palabras clave, la agrupación, los carriles y las casillas de verificación se muestran siempre, independientemente de esta configuración.',
            'kanban_limit_column' => 'Columna de la fecha límite.<br/>*Según la diferencia con el momento actual, la tarjeta muestra una insignia de "quedan", "vence pronto" o "vencido".<br/>*Un registro cuya columna se considera terminada muestra "cumplido" en su lugar.<br/>*<b>Si se deja vacía</b>, el tablero no tiene insignia de fecha límite, ni indicador "Vencidos", ni filtro "Solo vencidos", ni edición de la fecha límite en la tarjeta.',
            'kanban_sum_column' => 'Muestra el total de esta columna numérica bajo el encabezado de la columna del tablero.<br/>Ejemplo: elija un importe y el encabezado mostrará "Aprobación de dirección &yen;34,700,000", de modo que el dinero detenido en una columna se ve de un vistazo.<br/>*Solo visualización: no afecta al límite WIP.<br/>*Los separadores de miles y el símbolo de moneda siguen la configuración propia de esa columna.<br/>*Al filtrar el tablero, solo se totalizan las tarjetas que quedan en pantalla.',
            'kanban_blocked_keys' => 'Valores que indican que el trabajo se ha detenido. Sus tarjetas reciben un borde rojo y una bandera, y se añade "Bloqueado" a la fila de KPI y al panel de filtros.<br/>Ejemplo: "En espera" y "Devuelto" de una columna de estado, o "Sí" de una columna dedicada a bloqueos.<br/>*No tiene que ser la columna por la que se agrupa el tablero: se puede elegir cualquier valor de cualquier columna.<br/>*Esto permite distinguir el trabajo en curso del trabajo que se ha estancado.',
            'kanban_expedite_keys' => 'Valores que indican una interrupción urgente. Sus tarjetas reciben un contorno destacado y, cuando el tablero se divide por esa misma columna, el carril queda fijado en la parte superior.<br/>Ejemplo: "Urgente" de una columna de prioridad.<br/>*Las tarjetas urgentes nunca son rechazadas por "Mover a una columna llena", de acuerdo con la política habitual de Kanban de que una interrupción puede superar el límite. Aun así se cuentan, por lo que el coste de la interrupción sigue visible en pantalla.<br/>*Marcar muchos valores como urgentes hace que la marca pierda su sentido: limítelo a uno o dos.',
            'kanban_hide_keys' => 'No se dibujan las columnas del tablero correspondientes a los valores elegidos.<br/>Ejemplo: excluya "Terminado" y "Cancelado" y el tablero mostrará solo el trabajo que sigue en curso.<br/>*Sus registros nunca se leen, por lo que en una tabla grande esto por sí solo hace que el tablero sea mucho más rápido.<br/>*También quedan excluidos de los totales, los promedios y la fila de KPI.<br/>*En un tablero de flujo de trabajo, mover un registro a un estado oculto hace que su tarjeta desaparezca del tablero (el registro en sí no se modifica).<br/>*La columna "sin establecer" no se puede ocultar.<br/>*Se ignora un ajuste que no coincida con los carriles mostrados actualmente.',
            'kanban_col_count' => 'Número de tarjetas que carga cada columna al principio.<br/>0 (vacío) mantiene el comportamiento anterior: una sola consulta para todo el tablero, hasta el número máximo de registros.<br/>Si indica 50, cada columna carga 50 tarjetas con un botón "Cargar más" debajo.<br/>*Los recuentos, los totales, los días promedio y la fila de KPI se calculan entonces sobre toda la tabla, no sobre las tarjetas que estén cargadas.<br/>*Se recomienda cuando una tabla contiene miles de registros: el número máximo de registros ya no limita el tablero.<br/>*Las calles configuradas en la vista lo conservan: cada celda (columna x calle) muestra su propio recuento, calculado sobre toda la tabla.<br/>*Un filtro, una búsqueda por palabra clave, otra agrupación o una calle elegida en pantalla en lugar de en la vista vuelven a calcularse solo con las tarjetas ya cargadas.',
            'kanban_col_age' => 'Muestra, bajo el encabezado del carril, cuántos días de media llevan allí las tarjetas de ese carril.<br/>*Señala el paso en el que se acumula el trabajo.<br/>*Se cuenta desde el momento en que el registro llegó a su estado en un tablero de flujo de trabajo y, en otro caso, desde su última edición.',
            'kanban_progress_column' => 'Columna numérica que se dibuja como barra de progreso bajo el título de la tarjeta.<br/>*0-49 % azul, 50-99 % naranja, 100 % verde.<br/>*Las tarjetas con valor vacío no muestran barra.',
            'kanban_progress_max' => 'Valor que la barra de progreso considera como 100 %.<br/>Ejemplo: 100 para un porcentaje, 10 para un proceso de diez pasos.<br/>*El valor predeterminado es 100.',
            'kanban_history' => 'Muestra el historial del flujo de trabajo (cuándo, quién y qué acción) en el panel de detalle de la tarjeta.<br/>*Se carga solo para la tarjeta abierta, por lo que el tablero sigue siendo tan rápido como antes.<br/>*Solo se muestra en tablas que usan un flujo de trabajo.',
            'kanban_wip_column' => 'Calcula el límite WIP como la suma de esta columna numérica en lugar del número de tarjetas.<br/>Ejemplo: elija una cantidad y el encabezado del carril mostrará "1550/1200".<br/>*Déjelo vacío para seguir contando tarjetas.<br/>*Solo se pueden elegir columnas de tipo entero, decimal y moneda.',
            'kanban_limit_warn' => 'Una tarjeta que esté más cerca de su fecha límite que este número de horas se vuelve amarilla.<br/>Ejemplo: 2 para un ticket de soporte, 48 (=2 días) para una fecha de entrega.<br/>*Vacío significa 2 horas.',
            'kanban_age_steps' => 'Tres números de días en orden ascendente, separados por comas, que vuelven el borde de la tarjeta amarillo, naranja y rojo.<br/>Ejemplo: 1,2,3 para un ticket, 3,7,14 para un proceso largo.<br/>*Cualquier valor que no sean tres números ascendentes se trata como 1,2,3.',
            'kanban_age_column' => 'Columna de fecha desde la que se cuentan los días transcurridos (por ejemplo, la fecha de apertura).<br/>*El borde izquierdo de la tarjeta se colorea según la antigüedad (1 día amarillo, 2 días naranja, 3 días o más rojo).<br/>*También se usa en el resumen "Prom. días transcurridos".',
            'kanban_ai_column' => 'Columna usada para elegir un responsable recomendado (por ejemplo, el grupo de asignación).<br/>*Se recomienda para las tarjetas sin asignar a la persona que gestiona ese valor con más frecuencia.<br/>*El botón "Asignación automática" solo aparece cuando se han configurado tanto esta opción como "Columna del responsable".',
            'kanban_cover_column' => 'Columna de imagen que se muestra como portada en la parte superior de la tarjeta.<br/>*Los registros sin imagen no muestran portada.<br/>*Cuando hay varias imágenes guardadas, se usa la primera.<br/>*La imagen se sube a esta columna en el formulario de edición de datos.',
            'kanban_cover_fit' => 'Cómo se coloca la imagen de portada en su recuadro.<br/>*"Rellenar" cubre todo el recuadro y recorta lo que sobra.<br/>*"Ajustar imagen completa" muestra la imagen entera con márgenes laterales.',
            'kanban_labels_column' => 'Columna de selección que se muestra como etiquetas de color en la parte superior de la tarjeta.<br/>*También funciona una columna de varios valores: cada valor recibe su propia etiqueta.<br/>*La columna también se añade al panel de filtros, que muestra las tarjetas que tengan cualquiera de las etiquetas.',
            'kanban_labels_style' => 'Aspecto de las etiquetas.<br/>*"Chip" es una etiqueta pequeña con texto; "Barra de color" es una franja fina de color (estilo Trello).',
            'kanban_badge_column' => 'Columna que se muestra como una pequeña insignia en la esquina superior derecha de la tarjeta (un recuento, puntos, un número...).<br/>*Los registros con valor vacío no muestran insignia.',
            'kanban_kpi' => 'Si es SÍ, se muestra encima del tablero una barra de resumen con los recuentos.',
            'kanban_quickadd' => 'Si es SÍ, cada carril tiene un cuadro de entrada que crea un registro con la tecla Enter.<br/>*Solo se rellenan la columna de etiqueta y el valor de ese carril.',
            'kanban_bulk' => 'Si es SÍ, Shift+clic selecciona varias tarjetas para poder cambiarlas a la vez.',
            'kanban_editform' => 'Si es SÍ, al hacer clic en una tarjeta se abre el formulario de edición de ese registro sobre el tablero. Al guardar, el formulario se cierra y se vuelve a dibujar solo esa tarjeta.<br/>*No se muestra a quien no tenga permiso de edición.<br/>*Si es NO, el ajuste "panel de detalle" de abajo decide qué ocurre al hacer clic.',
            'kanban_drawer' => 'Si es SÍ, al hacer clic en una tarjeta se abre un panel de detalle a la derecha.<br/>*Si es NO, se abre en su lugar la página del registro.<br/>*Si "abrir el formulario de edición" de arriba también es SÍ, el clic abre el formulario y el panel se abre con el botón "i" de la esquina superior derecha de la tarjeta.',
            'kanban_position' => 'Lugar de la tarjeta en el que se muestra esta columna.',
            'kanban_style' => 'Muestra esta columna en la tarjeta con el ajuste predefinido elegido.<br/>Tiene prioridad sobre la configuración de la columna.<br/>Use el botón del lápiz para crear o editar un ajuste predefinido.<br/>Si se deja vacío, la tarjeta sigue la configuración de la columna y, si no la hay, muestra "nombre y valor".',
            'kanban_icon' => 'Un nombre de clase de Font Awesome, por ejemplo fa-phone.<br/>Para dar a cada opción su propio icono, introduzca pares "valor:clase" separados por comas.<br/>Ejemplo: phone:fa-phone,mail:fa-envelope,chat:fa-comments',
        ],
