        'message' => [
            'over_filters_max' => 'No se pueden establecer 6 o más filtros de visualización.',
            'over_sorts_max' => 'No se pueden establecer 6 o más criterios de ordenación.',
            'used_notify_error' => 'Se usa en la configuración de notificaciones. Elimínela primero.',
            'used_column_error' => 'Se usa como vista de filtrado en la configuración de columnas personalizadas. Elimínela primero.',
            'preview_not_supported' => 'Este tipo de vista no tiene vista previa. Está disponible para la lista de datos, el tablero Kanban y el diagrama de Gantt.',
            'preview_skipped' => ':count fila(s) de la configuración de la vista (columnas, filtros y ordenaciones de la vista) se omiten en esta vista previa: aún no se ha elegido su columna de destino o su condición de filtro.',
            'filter_ignored' => 'Se ha ignorado un filtro de visualización sin condición. Abra la pantalla de configuración de la vista y vuelva a elegir la condición.',
            'kanban_no_group_column' => 'No se ha establecido la columna de los carriles Kanban. Abra la configuración de la vista y seleccione "Columna de los carriles Kanban".',
            'kanban_group_column_required' => 'Seleccione "Columna de los carriles Kanban". Sin ella no se puede dibujar un tablero creado a partir de una columna de selección.',
            'kanban_age_steps_format' => 'Introduzca "Niveles de color por antigüedad" con el formato "1,2,3" (3 números separados por comas, en orden ascendente).',
            'gantt_no_date_setting' => 'El diagrama de Gantt necesita tanto la columna de fecha de inicio como la columna de fecha de fin. Elíjalas en la pantalla de configuración de la vista.',
            'gantt_over_limit' => 'El número de registros supera el límite (%s). Redúzcalo con el filtro de visualización.',
            'kanban_no_workflow' => 'No hay ningún flujo de trabajo activo aplicado a esta tabla. Configure un flujo de trabajo o vuelva a cambiar "Cómo se crean las columnas del tablero" a "A partir de los valores de una columna de selección".',
            'kanban_wf_no_action' => '%s no se puede mover a "%s". El flujo de trabajo no permite este movimiento o usted no puede ejecutarlo.',
            'kanban_wf_locked' => 'Este registro está bloqueado por el flujo de trabajo.',
            'kanban_wf_none' => 'Ahora mismo no hay ninguna acción del flujo de trabajo que usted pueda ejecutar en este registro.',
            'kanban_over_limit' => 'El número de registros supera el límite (%s). Redúzcalo con el filtro de visualización.',
            'kanban_partial' => 'Solo se muestran las %s tarjetas ya cargadas (de %s). Vuelva a la vista original para cargar más y ver las cifras de toda la tabla.',
            'kanban_wip_full' => '"%s" ha alcanzado su límite WIP (%s). ¿Desea continuar de todos modos?',
            'kanban_wip_blocked' => '"%s" ha alcanzado su límite WIP (%s) y no admite más tarjetas.',
            'kanban_search_capped' => 'Hay demasiadas coincidencias para mostrar: cada columna se detiene en las primeras %s. Precise más la palabra clave.',
            'kanban_move_error' => 'No se pudo actualizar. Vuelva a cargar la página.',
            'kanban_moved' => '%s se ha movido a "%s"',
            'kanban_inline_saved' => '%s guardado',
            'kanban_view_saved' => 'Se ha guardado la vista "%s". Se ha creado como vista propia y puede abrirse desde la lista de vistas.',
            'kanban_blank_filtered' => 'Ninguna tarjeta coincide con el filtro. Cámbielo o restablezca el tablero.',
            'kanban_created' => '%s añadido',
            'kanban_assigned' => 'Se ha cambiado el responsable de %s registros',
