    'role_group' => [
        'header' => 'Configuración de roles',
        'description' => 'Configure los grupos de roles. Un grupo de roles reúne varios permisos y controla el acceso de usuarios y organizaciones.',
        'role_group_name' => 'Nombre del grupo de roles',
        'role_group_view_name' => 'Nombre visible del grupo de roles',
        'description_system_admin' => '<span class="red">*Para añadir privilegios de administrador del sistema, vaya a "Configuración del sistema / Administrador del sistema" desde el menú.</span>',
        'role_group_id' => 'ID del grupo de roles',
